  assert.ok(summary.candidate_M_R_cauchy_tail_after_prefix_profile > 0);
  assert.ok(summary.candidate_M_G_cauchy_tail_after_prefix_profile > 0);
  assert.ok(summary.candidate_nu_J_cauchy_tail_loss_profile > 0);
